import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const ROLE = '인사 담당자';
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const USE_VALUES = ['사용', '미사용'];

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function requiredText(value: unknown, label: string, max?: number): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid(label + '을(를) 입력해 주세요.');
  }
  if (max !== undefined && value.length > max) {
    throw invalid(label + '은(는) ' + max + '자 이하여야 합니다.');
  }
  return value;
}

function useYnOf(value: unknown): string {
  if (typeof value !== 'string' || !USE_VALUES.includes(value)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return value;
}

function ruleIdOf(value: unknown): number {
  const n = typeof value === 'number' ? value : typeof value === 'string' && value.trim() !== '' ? Number(value) : NaN;
  if (!Number.isInteger(n)) {
    throw invalid('채번 규칙이 올바르지 않습니다.');
  }
  return n;
}

@Controller('api/v1')
export class FnSfr01601Controller {
  @Get('/certificate-forms')
  async listCertificateForms(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const query = checks.queryOf(req.query);
    const rawUse = query['useYn'];
    const useYn = rawUse === undefined || rawUse === null || rawUse === '' ? null : useYnOf(rawUse);
    const rawPage = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    const rawSize = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(rawPage) || rawPage < 0) {
      throw invalid('page가 올바르지 않습니다.');
    }
    if (!Number.isInteger(rawSize) || rawSize < 1) {
      throw invalid('size가 올바르지 않습니다.');
    }
    const page = rawPage;
    const size = Math.min(rawSize, MAX_SIZE);
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:useYn AS text) IS NULL OR use_yn = CAST(:useYn AS text))';
      const totalRows = await db.query('SELECT COUNT(*) AS "total" FROM certificate_form ' + where, { useYn });
      const items = await db.query(
        'SELECT certificate_form_id AS "certificateFormId", form_name AS "formName", use_yn AS "useYn", numbering_rule_id AS "numberingRuleId" '
          + 'FROM certificate_form ' + where + ' ORDER BY certificate_form_id DESC LIMIT :size OFFSET :offset',
        { useYn, size, offset: page * size },
      );
      return { items, page, size, total: Number(totalRows[0]['total']) };
    });
  }

  @Post('/certificate-forms')
  @HttpCode(200)
  async createCertificateForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const data = checks.inputOf(req.body);
    const formName = requiredText(data['formName'], '증명서 종류명', 200);
    const formContent = requiredText(data['formContent'], '양식 내용');
    const useYn = useYnOf(data['useYn']);
    const hasRule = data['numberingRuleId'] !== undefined && data['numberingRuleId'] !== null && data['numberingRuleId'] !== '';
    const ruleId = hasRule ? ruleIdOf(data['numberingRuleId']) : null;
    return transaction(async (db) => {
      if (ruleId !== null) {
        const rule = await db.query('SELECT numbering_rule_id FROM numbering_rule WHERE numbering_rule_id = CAST(:ruleId AS bigint)', { ruleId });
        if (rule.length === 0) {
          throw new ApiError(404, 'NUMBERING_RULE_NOT_FOUND', '연결할 채번 규칙이 존재하지 않습니다.');
        }
      }
      const dup = await db.query('SELECT certificate_form_id FROM certificate_form WHERE form_name = :formName', { formName });
      if (dup.length > 0) {
        throw new ApiError(409, 'CERTIFICATE_FORM_NAME_DUPLICATED', '동일한 증명서 종류명이 이미 등록되어 있습니다.');
      }
      // 변경 이력은 공통 모듈(공통 P15)이 맡는다.
      const rows = await db.query(
        'INSERT INTO certificate_form (numbering_rule_id, form_name, form_content, use_yn, created_at, updated_at) '
          + 'VALUES (CAST(:ruleId AS bigint), :formName, :formContent, :useYn, now(), now()) '
          + 'RETURNING certificate_form_id AS "certificateFormId"',
        { ruleId, formName, formContent, useYn },
      );
      return rows[0];
    });
  }

  @Patch('/certificate-forms/:certificateFormId')
  async updateCertificateForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['certificateFormId'];
    const data = checks.inputOf(req.body);
    const formName = data['formName'] === undefined ? null : requiredText(data['formName'], '증명서 종류명', 200);
    const formContent = data['formContent'] === undefined ? null : requiredText(data['formContent'], '양식 내용');
    const useYn = data['useYn'] === undefined ? null : useYnOf(data['useYn']);
    const setRule = data['numberingRuleId'] !== undefined;
    const hasRule = setRule && data['numberingRuleId'] !== null && data['numberingRuleId'] !== '';
    const ruleId = hasRule ? ruleIdOf(data['numberingRuleId']) : null;
    return transaction(async (db) => {
      if (!/^[0-9]+$/.test(id)) {
        throw new ApiError(404, 'CERTIFICATE_FORM_NOT_FOUND', '대상 양식이 존재하지 않습니다.');
      }
      const found = await db.query('SELECT certificate_form_id FROM certificate_form WHERE certificate_form_id = CAST(:id AS bigint)', { id });
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_FORM_NOT_FOUND', '대상 양식이 존재하지 않습니다.');
      }
      if (ruleId !== null) {
        const rule = await db.query('SELECT numbering_rule_id FROM numbering_rule WHERE numbering_rule_id = CAST(:ruleId AS bigint)', { ruleId });
        if (rule.length === 0) {
          throw new ApiError(404, 'NUMBERING_RULE_NOT_FOUND', '연결할 채번 규칙이 존재하지 않습니다.');
        }
      }
      if (formName !== null) {
        const dup = await db.query(
          'SELECT certificate_form_id FROM certificate_form WHERE form_name = :formName AND certificate_form_id <> CAST(:id AS bigint)',
          { formName, id },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'CERTIFICATE_FORM_NAME_DUPLICATED', '변경할 증명서 종류명이 이미 존재합니다.');
        }
      }
      // 변경 이력은 공통 모듈(공통 P15)이 맡는다.
      await db.execute(
        'UPDATE certificate_form SET '
          + 'form_name = COALESCE(CAST(:formName AS text), form_name), '
          + 'form_content = COALESCE(CAST(:formContent AS text), form_content), '
          + 'use_yn = COALESCE(CAST(:useYn AS text), use_yn), '
          + 'numbering_rule_id = CASE WHEN CAST(:setRule AS boolean) THEN CAST(:ruleId AS bigint) ELSE numbering_rule_id END, '
          + 'updated_at = now() WHERE certificate_form_id = CAST(:id AS bigint)',
        { formName, formContent, useYn, setRule, ruleId, id },
      );
      return { certificateFormId: Number(id) };
    });
  }

  @Delete('/certificate-forms/:certificateFormId')
  async deleteCertificateForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require(ROLE);
    const id = req.params['certificateFormId'];
    return transaction(async (db) => {
      if (!/^[0-9]+$/.test(id)) {
        throw new ApiError(404, 'CERTIFICATE_FORM_NOT_FOUND', '대상 양식이 존재하지 않습니다.');
      }
      const found = await db.query('SELECT certificate_form_id FROM certificate_form WHERE certificate_form_id = CAST(:id AS bigint)', { id });
      if (found.length === 0) {
        throw new ApiError(404, 'CERTIFICATE_FORM_NOT_FOUND', '대상 양식이 존재하지 않습니다.');
      }
      const used = await db.query('SELECT COUNT(*) AS "cnt" FROM certificate WHERE certificate_form_id = CAST(:id AS bigint)', { id });
      if (Number(used[0]['cnt']) > 0) {
        throw new ApiError(409, 'CERTIFICATE_FORM_IN_USE', '신청 건이 있는 양식은 삭제할 수 없습니다. 미사용으로 전환해 주세요.');
      }
      await db.execute('DELETE FROM certificate_form WHERE certificate_form_id = CAST(:id AS bigint)', { id });
      return {};
    });
  }
}

