import { useState } from 'react';
import {
  call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Pairs, Form, Field,
  TextInput, Select, LookupSelect, RefName, ErrorText,
} from '../kit';
import type { PageProps, Page, Row } from '../kit';

const SIZE = 20;
const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];

type Mode =
  | { type: 'create' }
  | { type: 'detail'; row: Row }
  | { type: 'edit'; row: Row }
  | { type: 'delete'; row: Row }
  | null;

export default function FnSfr01601Page({ role, notify }: PageProps) {
  const [useYn, setUseYn] = useState('');
  const [applied, setApplied] = useState('');
  const [page, setPage] = useState(0);
  const [mode, setMode] = useState<Mode>(null);

  const { data, error, reload } = useData<Page>(
    () => call<Page>('GET', '/certificate-forms', role, undefined, { useYn: applied, page, size: SIZE }),
    [applied, page, role],
  );

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;

  function done(text: string) {
    notify(text);
    setMode(null);
    reload();
  }

  async function switchUse(row: Row) {
    const next = row['useYn'] === '사용' ? '미사용' : '사용';
    await call('PATCH', '/certificate-forms/' + String(row['certificateFormId']), role, { useYn: next });
    done('사용 여부를 ' + next + '(으)로 변경했습니다.');
  }

  return (
    <div className='bento'>
      <section className='box span-4'>
        <h2>조회 건수</h2>
        <Num value={total} />
      </section>
      <section className='box span-8'>
        <h2>증명서 양식</h2>
        <Filters
          onSearch={() => { setPage(0); setApplied(useYn); }}
          onReset={() => { setUseYn(''); setApplied(''); setPage(0); }}
        >
          <Field label='사용 여부'>
            <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} placeholder='전체' />
          </Field>
        </Filters>
        <Band total={total}>
          <button type='button' onClick={() => setMode({ type: 'create' })}>양식 등록</button>
        </Band>
        {error ? <ErrorText text={error} /> : null}
        <DataTable
          rows={rows}
          onRowClick={(row) => setMode({ type: 'detail', row })}
          empty='등록된 증명서 양식이 없습니다.'
          columns={[
            { key: 'formName', label: '증명서 종류명' },
            { key: 'useYn', label: '사용 여부', render: (r) => <Badge value={r['useYn']} /> },
            {
              key: 'numberingRuleId',
              label: '채번 규칙',
              render: (r) => (r['numberingRuleId'] ? <RefName table='numbering_rule' role={role} value={r['numberingRuleId']} /> : <span>-</span>),
            },
          ]}
        />
        <Pager page={page} size={SIZE} total={total} onPage={setPage} />
      </section>

      {mode && mode.type === 'detail' ? (
        <Drawer title='증명서 양식' onClose={() => setMode(null)}>
          <Pairs
            items={[
              ['증명서 종류명', String(mode.row['formName'])],
              ['사용 여부', <Badge value={mode.row['useYn']} />],
              [
                '채번 규칙',
                mode.row['numberingRuleId'] ? <RefName table='numbering_rule' role={role} value={mode.row['numberingRuleId']} /> : '-',
              ],
            ]}
          />
          <Band>
            <button type='button' onClick={() => setMode({ type: 'edit', row: mode.row })}>수정</button>
            <button type='button' onClick={() => switchUse(mode.row)}>
              {mode.row['useYn'] === '사용' ? '미사용으로 전환' : '사용으로 전환'}
            </button>
            <button type='button' onClick={() => setMode({ type: 'delete', row: mode.row })}>삭제</button>
          </Band>
        </Drawer>
      ) : null}

      {mode && mode.type === 'create' ? (
        <FormDrawer title='증명서 양식 등록' role={role} row={null} onClose={() => setMode(null)} onDone={done} />
      ) : null}

      {mode && mode.type === 'edit' ? (
        <FormDrawer title='증명서 양식 수정' role={role} row={mode.row} onClose={() => setMode(null)} onDone={done} />
      ) : null}

      {mode && mode.type === 'delete' ? (
        <Drawer title='증명서 양식 삭제' onClose={() => setMode(null)}>
          <Form
            submit='삭제'
            danger
            note={'\'' + String(mode.row['formName']) + '\' 양식을 삭제합니다. 신청 건이 있으면 삭제할 수 없으니 미사용으로 전환해 주세요.'}
            onSubmit={async () => {
              await call('DELETE', '/certificate-forms/' + String(mode.row['certificateFormId']), role);
              done('삭제했습니다.');
            }}
          />
        </Drawer>
      ) : null}
    </div>
  );
}

function FormDrawer({ title, role, row, onClose, onDone }: {
  title: string;
  role: string;
  row: Row | null;
  onClose: () => void;
  onDone: (text: string) => void;
}) {
  const editing = row !== null;
  const [formName, setFormName] = useState(row ? String(row['formName']) : '');
  const [formContent, setFormContent] = useState('');
  const [useYn, setUseYn] = useState(row ? String(row['useYn']) : '사용');
  const [ruleId, setRuleId] = useState<number | string>(row && row['numberingRuleId'] ? Number(row['numberingRuleId']) : '');

  return (
    <Drawer title={title} onClose={onClose}>
      <Form
        submit={editing ? '수정' : '등록'}
        onSubmit={async () => {
          if (formName.trim() === '') {
            throw new Error('증명서 종류명을 입력해 주세요.');
          }
          if (!editing && formContent.trim() === '') {
            throw new Error('양식 내용을 입력해 주세요.');
          }
          if (useYn === '') {
            throw new Error('사용 여부를 선택해 주세요.');
          }
          const body: Row = { formName, useYn };
          if (formContent.trim() !== '') {
            body['formContent'] = formContent;
          }
          if (ruleId !== '') {
            body['numberingRuleId'] = ruleId;
          }
          if (editing && row) {
            await call('PATCH', '/certificate-forms/' + String(row['certificateFormId']), role, body);
            onDone('수정했습니다.');
          } else {
            await call('POST', '/certificate-forms', role, body);
            onDone('등록했습니다.');
          }
        }}
      >
        <Field label='증명서 종류명' required>
          <TextInput value={formName} onChange={setFormName} />
        </Field>
        <Field label='양식 내용' required={!editing} wide hint={editing ? '비워 두면 기존 내용을 유지합니다.' : undefined}>
          <TextInput value={formContent} onChange={setFormContent} multiline />
        </Field>
        <Field label='사용 여부' required>
          <Select value={useYn} onChange={setUseYn} options={USE_OPTIONS} />
        </Field>
        <Field label='채번 규칙'>
          <LookupSelect table='numbering_rule' role={role} value={ruleId} onChange={setRuleId} placeholder='선택 안 함' />
        </Field>
      </Form>
    </Drawer>
  );
}
